    'install.code.prebuilt': '<span class="text-paper/35"># macOS / Linux</span> tar xzf wyj-code-*.tar.gz &amp;&amp; cd wyj-code-*/ &amp;&amp; ./install.sh  <span class="text-paper/35"># Windows (inside the extracted folder)</span> install.bat  <span class="text-paper/35"># upgrade later</span> wyj-code update',
